// ============================================
// FILTER ANOMALY EVENTS
// ============================================

const items = $input.all();
const anomalyEvents = [];

for (const item of items) {
  const data = item.json;

  let event = data.event || data;
  if (typeof event === 'string') {
    try {
      event = JSON.parse(event);
    } catch (e) {
      continue;
    }
  }

  if (event.event === 'reconciliation.anomaly' || event.type === 'reconciliation.anomaly') {
    anomalyEvents.push({
      json: {
        event_id: data.id || `anomaly_${Date.now()}`,
        event_type: 'reconciliation.anomaly',
        guild_id: event.guild_id,
        anomaly_type: event.data?.anomaly_type || event.anomaly_type || 'unknown',
        severity: event.data?.severity || event.severity || 'warning',
        description: event.data?.description || event.description || 'Anomalie detectee',
        affected_users: event.data?.affected_users || [],
        details: event.data?.details || {},
        timestamp: event.timestamp || new Date().toISOString()
      }
    });
  }
}

return anomalyEvents.length > 0 ? anomalyEvents : [];

// ============================================
// PREPARE ADMIN ALERT EMBED
// ============================================

const data = $input.first().json;

const severityConfig = {
  critical: { color: 0xE74C3C, icon: '🚨', title: 'ALERTE CRITIQUE' },
  warning: { color: 0xE67E22, icon: '⚠️', title: 'Alerte' },
  info: { color: 0x3498DB, icon: 'ℹ️', title: 'Information' }
};

const config = severityConfig[data.severity] || severityConfig.warning;

const embed = {
  title: `${config.icon} ${config.title}: ${data.anomaly_type}`,
  description: data.description,
  color: config.color,
  fields: [
    {
      name: 'Type',
      value: data.anomaly_type,
      inline: true
    },
    {
      name: 'Severite',
      value: data.severity.toUpperCase(),
      inline: true
    },
    {
      name: 'Utilisateurs affectes',
      value: data.affected_users.length > 0 ? data.affected_users.length.toString() : 'N/A',
      inline: true
    }
  ],
  footer: { text: 'Systeme de reconciliation' },
  timestamp: data.timestamp
};

if (Object.keys(data.details).length > 0) {
  embed.fields.push({
    name: 'Details',
    value: '```json\n' + JSON.stringify(data.details, null, 2).substring(0, 900) + '\n```',
    inline: false
  });
}

return {
  type: 'webhook',
  guild_id: data.guild_id,
  target: 'admin',
  content: data.severity === 'critical' ? '@here' : null,
  embed: embed,
  notification_type: 'admin_alert',
  severity: data.severity,
  source: 'n8n:ALERT-Anomaly-Detected',
  event_id: data.event_id,
  timestamp: new Date().toISOString()
};

